                let value = line.trim();
                if !value.is_empty() { events.push(value.to_string()); }
            }
        }
    }
    events.sort(); events.dedup();
    let source = std::path::Path::new(a).file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    Ok(Pack { t, c, e: events, n: recs.len() as u32, s: source, w: digest(&names.join("\n"))? })
}
